let history=[],future=[],group=null,saveTimer,toastTimer,renderToken=0,uploadMode='image',storageProblem=false;
let fontBusy=false,fontNotice='',fontSample='Un momento especial';
let audioBusy=false,audioNotice='',playbackContext=null,playbackFrame=0,playbackSerial=0,videoController=null;
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved){state.library=(saved.library||[]).map(d=>validateDesign(d));state.design=validateDesign(saved.design);state.selected=state.design.elements.find(e=>e.type==='text')?.id??null;}}catch{storageProblem=true;}
const getSelected=()=>state.design.elements.find(e=>e.id===state.selected);
const activeDesign=()=>state.mode==='customer'?state.customer:state.design;
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function saveNow(){clearTimeout(saveTimer);try{localStorage.setItem(STORAGE,JSON.stringify({design:state.design,library:state.library}));storageProblem=false;setStatus('Guardado en este navegador');}catch{storageProblem=true;setStatus('Sin guardar · exporta una copia');toast('No hay espacio para guardar. Descarga una copia del diseño en Mis diseños.');}}
function setStatus(text){const s=$('#save-text');if(s)s.textContent=text;}
function queueSave(){setStatus('Guardando…');clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,450);}
function remember(key=null){if(!key||group!==key){history.push(clone(state.design));if(history.length>70)history.shift();}group=key;future=[];}
function changed({props=false,left=false}={}){syncFontRefs(state.design);state.design.updatedAt=Date.now();queueSave();draw();updateHistoryButtons();if(props)renderProperties();if(left)renderLeft();}
function updateHistoryButtons(){const u=$('[data-action=undo]'),r=$('[data-action=redo]');if(u)u.disabled=!history.length;if(r)r.disabled=!future.length;}
function brand(){return `<div class="brand"><img class="brand-logo" src="./assets/lumimila-logo-web.svg" alt="Lumimila · Clipart & Illustrations"><span class="studio-label">Estudio de invitaciones</span></div>`;}
function render(){
  stopPlayback();
  if(state.mode==='customer'){renderCustomer();return;}
  $('#app').innerHTML=`<div class="app-shell"><header class="topbar">${brand()}<div class="top-actions"><span class="save-status"><i class="save-dot"></i><span id="save-text">${storageProblem?'Sin guardar · exporta una copia':'Guardado en este navegador'}</span></span>${button('library','Mis diseños','templates')}${button('customer','Vista del cliente','eye')}${button('download','Descargar','download','primary')}</div></header>
  <div class="projectbar"><div class="project-left"><span class="breadcrumb">Tu espacio creativo</span><div class="project-name"><span id="project-name">${esc(state.design.name)}</span>${ib('rename','Cambiar nombre del diseño','edit')}</div><span class="tag">Borrador</span></div><div class="project-tools">${ib('undo','Deshacer (⌘Z)','undo',history.length?'':'disabled')}${ib('redo','Rehacer (⌘⇧Z)','redo',future.length?'':'disabled')}<div class="divider"></div>${button('save-template','Guardar plantilla','save','small soft')}</div></div>
  <nav class="mobile-panel-tabs" aria-label="Panel del editor">${[['tools','Herramientas'],['canvas','Invitación'],['properties','Propiedades']].map(([id,label])=>`<button data-mobile="${id}" class="${state.mobile===id?'active':''}">${label}</button>`).join('')}</nav>
  <main class="workspace" data-mobile="${state.mobile}"><aside class="left-panel" aria-label="Herramientas"><nav class="panel-tabs">${[['text','Texto'],['image','Imágenes'],['background','Fondos'],['shapes','Elementos'],['layers','Capas'],['templates','Plantillas'],['fonts','Mis fuentes'],['motion','Animación']].map(([id,label])=>`<button class="tool-tab ${state.tab===id?'active':''}" data-tab="${id}" aria-label="${label}">${icon(id==='fonts'?'text':id)}<span>${label}</span></button>`).join('')}</nav><div class="panel-content" id="left-content"></div></aside>
  <section class="canvas-area" aria-label="Lienzo de la invitación"><div class="canvas-heading"><span>Un momento para celebrar</span><span>5 × 7 pulgadas · Vertical</span></div><div class="stage-viewport"><div class="canvas-wrap" id="canvas-wrap"><canvas id="design-canvas" tabindex="0" aria-label="Invitación editable. Selecciona un elemento para moverlo con las flechas del teclado."></canvas><div id="selection"></div></div></div><div class="canvas-footer"><span class="footer-caption">Hecha por ti, para un día especial.</span><div class="zoom-control">${ib('zoom-out','Alejar','minus')}<span id="zoom-label">100%</span>${ib('zoom-in','Acercar','plus')}<div class="divider"></div>${ib('zoom-fit','Ajustar al espacio','fit')}</div><span>300 ppp al descargar</span></div></section>
  <aside class="right-panel" id="properties" aria-label="Propiedades del elemento"></aside></main></div>`;
  renderLeft();renderProperties();requestAnimationFrame(()=>{fitStage();draw();});
}
function renderLeft(){
  const dest=$('#left-content');if(!dest)return;
  document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));
  const layerList=()=>`<div class="layer-list">${[...state.design.elements].reverse().map(e=>`<button class="layer-row ${e.id===state.selected?'selected':''}" data-select="${esc(e.id)}">${icon(e.type==='shape'?'shapes':e.type)}<span class="layer-label">${esc(e.label||e.text)}</span>${e.editable?'<i class="editable-dot" title="Editable por el cliente"></i>':''}${e.locked?icon('lock','lock-indicator'):''}</button>`).join('')}<button class="layer-row" data-tab="background">${icon('background')}<span class="layer-label">Fondo de la invitación</span>${icon('lock','lock-indicator')}</button></div>`;
  if(state.tab==='fonts'){renderFontsPanel(dest);return;}
  if(state.tab==='motion'){renderMotionPanel(dest);return;}
  if(state.tab==='text')dest.innerHTML=`<div class="eyebrow">Dilo a tu manera</div><h2 class="panel-title">Añade un texto</h2><p class="help">Cada palabra hace tu diseño único.</p><button class="text-preset large" data-add-text="title">Añadir un título</button><button class="text-preset medium" data-add-text="subtitle">Añadir un subtítulo</button><button class="text-preset small" data-add-text="body">Añadir un texto pequeño</button><hr class="section-line"><div class="eyebrow">En tu invitación</div>${layerList()}<div class="hint-card">${icon('spark')}<strong>Tu diseño, sus detalles</strong><p class="help">Activa «Editable por el cliente» en los textos que quieras personalizar.</p></div>`;
  if(state.tab==='layers')dest.innerHTML=`<div class="eyebrow">Todo en su lugar</div><h2 class="panel-title">Capas del diseño</h2><p class="help">Las capas de arriba se muestran al frente.</p><hr class="section-line">${layerList()}`;
  if(state.tab==='image')dest.innerHTML=`<div class="eyebrow">Un toque personal</div><h2 class="panel-title">Tus imágenes</h2><p class="help">Fotografías, ilustraciones o tus propios adornos.</p><hr class="section-line"><button class="upload-area" data-action="upload-image">${icon('upload')}<strong>Subir una imagen</strong><small>PNG, JPG o WebP · hasta 12 MB</small></button><div class="hint-card">${icon('image')}<strong>Hazlo tuyo</strong><p class="help">Mueve la imagen sobre el lienzo y ajusta su tamaño desde la esquina.</p></div>`;
  if(state.tab==='background')dest.innerHTML=`<div class="eyebrow">El escenario perfecto</div><h2 class="panel-title">Fondo de tu invitación</h2><div class="field" style="margin-top:20px"><label for="bg-color">Color del papel</label><input id="bg-color" type="color" data-background="color" value="${state.design.background}"></div><button class="bg-thumb" data-action="birthday-background"><img src="./assets/fiesta-bg.png" alt="Globos y regalos de colores"><span><strong>Un día de colores</strong><small>Cumpleaños infantil</small></span></button><hr class="section-line"><button class="upload-area" data-action="upload-background">${icon('upload')}<strong>Subir mi propio fondo</strong><small>Usa una imagen vertical, proporción 5:7.</small></button>${state.design.backgroundImage?button('remove-background','Usar solo color','background','full small','style="margin-top:12px"'):''}`;
  if(state.tab==='shapes')dest.innerHTML=`<div class="eyebrow">Pequeños detalles</div><h2 class="panel-title">Elementos</h2><p class="help">Añade una forma y elige su color.</p><div class="shape-grid">${[['star','★','Estrella'],['heart','♥','Corazón'],['circle','●','Círculo'],['rect','■','Rectángulo'],['line','—','Línea']].map(([id,symbol,label])=>`<button data-shape="${id}" title="${label}" aria-label="Añadir ${label.toLowerCase()}">${symbol}</button>`).join('')}</div><div class="hint-card">${icon('layers')}<strong>Juega con las capas</strong><p class="help">Puedes enviar un elemento al fondo o traerlo al frente desde sus propiedades.</p></div>`;
  if(state.tab==='templates')dest.innerHTML=`<div class="eyebrow">El comienzo de algo bonito</div><h2 class="panel-title">Tus plantillas</h2><button class="bg-thumb" data-action="new-birthday"><img src="./assets/fiesta-bg.png" alt="Invitación de cumpleaños"><span><strong>Un día de colores</strong><small>Personaliza este diseño</small></span></button>${button('new-blank','Empezar en blanco','plus','full','style="margin-top:12px"')}<hr class="section-line">${button('library','Ver mis diseños','templates','full')}${button('import','Importar un diseño','upload','full small','style="margin-top:10px"')}<p class="local-note">Tus diseños se guardan en este navegador. Exporta una copia para conservarlos o llevarlos a otro dispositivo.</p>`;
}
function renderAudioChoices(design,customer=false){
  const options=design.audioOptions||[];if(customer&&!options.length)return '';
  return `<div class="audio-choices"><div class="eyebrow">${customer?'Elige la música de tu invitación':'Tus opciones de audio'}</div>${options.map((audio,i)=>`<div class="audio-choice ${design.audio?.id===audio.id?'selected':''}"><button class="audio-pick" data-action="choose-audio" data-id="${audio.id}" aria-pressed="${design.audio?.id===audio.id}" aria-label="Elegir audio ${i+1}: ${esc(audio.name)}" type="button"><span class="choice-dot"></span><span><strong>${esc(audio.name)}</strong><small>${audio.duration.toFixed(1)} segundos</small></span></button>${ib('listen-audio',`Escuchar audio ${i+1}`,'play',`data-id="${audio.id}" type="button"`)}${customer?'':ib('remove-audio',`Quitar audio ${i+1}`,'trash',`data-id="${audio.id}" type="button"`)}</div>`).join('')}<button class="silent-choice ${!design.audio?'selected':''}" data-action="choose-audio" data-id="" aria-pressed="${!design.audio}" type="button"><span class="choice-dot"></span>Sin audio</button></div>`;
}
function renderMotionPanel(dest){
  const effect=state.design.animation||'none',options=state.design.audioOptions||[];
  dest.innerHTML=`<div class="eyebrow">Una invitación con vida</div><h2 class="panel-title">Movimiento y música</h2><p class="help">Un pequeño adelanto de la celebración.</p><div class="effect-grid">${[['sparkle','Brillo','✦','Destellos suaves'],['confetti','Confeti','▰','Una lluvia de color'],['bubbles','Burbujas','◌','Flotan suavemente']].map(([id,name,mark,desc])=>`<button class="effect-card ${effect===id?'selected':''}" data-action="set-effect" data-effect="${id}" aria-pressed="${effect===id}" aria-label="Animación ${name}"><span class="effect-art ${id}"><i>${mark}</i><i>${mark}</i><i>${mark}</i></span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><button class="silent-choice ${effect==='none'?'selected':''}" data-action="set-effect" data-effect="none" aria-pressed="${effect==='none'}"><span class="choice-dot"></span>Sin animación</button>${button('preview-motion','Ver animación y escuchar','eye','full motion-preview')}<hr class="section-line">${renderAudioChoices(state.design)}<button class="upload-area audio-upload" data-action="upload-audio" ${audioBusy||options.length>=3?'disabled':''}>${icon('upload')}<strong>${audioBusy?'Preparando audio…':`Subir audio · ${options.length}/3`}</strong><small>MP3, WAV, M4A, AAC u OGG · hasta 20 MB</small></button><p class="font-notice" role="status">${esc(audioNotice)}</p>${state.design.audio?`<div class="field"><label for="audio-volume">Volumen <span id="audio-volume-value">${Math.round(state.design.audio.volume*100)}%</span></label><input id="audio-volume" type="range" min="0" max="100" value="${Math.round(state.design.audio.volume*100)}"></div>`:''}<p class="local-note">El cliente podrá escuchar y elegir uno de tus 3 audios. Usamos los primeros 15 segundos de cada archivo.</p><div class="hint-card">${icon('download')}<strong>Listo para compartir</strong><p class="help">Descarga un video MP4 de 15 segundos con tu animación y el audio elegido.</p></div>`;
}
function chooseAudio(id){
  stopPlayback();const design=activeDesign(),selected=(design.audioOptions||[]).find(a=>a.id===id);if(id&&!selected)return;
  if(state.mode==='editor')remember();design.audio=selected?{...selected}:null;
  if(state.mode==='customer'){saveCustomer();renderCustomer();}else changed({left:true});
}
function stopPlayback(){
  playbackSerial++;cancelAnimationFrame(playbackFrame);playbackFrame=0;
  $('#modal video')?.pause();
  if(playbackContext){playbackContext.close().catch(()=>{});playbackContext=null;}
  document.querySelectorAll('[data-listening]').forEach(b=>{b.removeAttribute('data-listening');b.classList.remove('playing');});
}
async function listenAudio(id){
  const same=document.querySelector(`[data-listening="${id}"]`);stopPlayback();if(same)return;
  const ref=(activeDesign().audioOptions||[]).find(a=>a.id===id);if(!ref)return;
  const ctx=new AudioContext();playbackContext=ctx;const token=playbackSerial;
  try{await ctx.resume();if(token!==playbackSerial)return;const source=ctx.createBufferSource();source.buffer=audioBuffer(ref);source.connect(ctx.destination);document.querySelectorAll(`[data-action="listen-audio"][data-id="${id}"]`).forEach(b=>{b.dataset.listening=id;b.classList.add('playing');});source.onended=()=>{if(token===playbackSerial)stopPlayback();};source.start();}catch(e){stopPlayback();throw e;}
}
async function previewAnimation(){
  const design=clone(activeDesign());openModal('Así se verá tu invitación','15 segundos · Movimiento, letras y música a tu manera.',`<div class="motion-player"><canvas id="motion-preview" aria-label="Vista previa animada de la invitación"></canvas><div class="playback-time" id="playback-time" role="status">Preparando vista previa…</div></div>`,button('replay-motion','Volver a reproducir','eye','small'));
  const ctxAudio=design.audio?new AudioContext():null;playbackContext=ctxAudio;const token=playbackSerial;
  if(ctxAudio)await ctxAudio.resume();
  try{
    const base=document.createElement('canvas');await renderDesign(base,design,1.4);if(token!==playbackSerial)return;
    const canvas=$('#motion-preview');canvas.width=base.width;canvas.height=base.height;const ctx=canvas.getContext('2d');
    let audio;if(design.audio){audio=ctxAudio.createBufferSource();audio.buffer=audioBuffer(design.audio);audio.connect(ctxAudio.destination);audio.start();}
    const start=performance.now();const tick=now=>{if(token!==playbackSerial||!canvas.isConnected)return;const time=Math.min(15,(now-start)/1000);ctx.drawImage(base,0,0);drawEffect(ctx,design.animation,time,canvas.width,canvas.height);$('#playback-time').textContent=`${time.toFixed(1)} / 15 s${design.audio?' · Con audio':' · Sin audio'}`;if(time<15)playbackFrame=requestAnimationFrame(tick);else stopPlayback();};playbackFrame=requestAnimationFrame(tick);
  }catch(e){if(token===playbackSerial){stopPlayback();$('#playback-time').textContent=e.message;}}
}
async function downloadVideo(){
  const design=clone(activeDesign());openModal('Creando tu video','Tu invitación está tomando vida.',`<div class="video-progress">${icon('spark')}<strong id="video-progress-text" role="status">Preparando el diseño…</strong><progress id="video-progress" max="100" value="0"></progress><p class="help">Puedes cancelar cerrando esta ventana.</p></div>`);
  const controller=new AbortController();videoController=controller;
  try{
    const blob=await exportVideo(design,{signal:controller.signal,onProgress:f=>{if(!controller.signal.aborted){$('#video-progress').value=Math.round(f*100);$('#video-progress-text').textContent=`Creando tu MP4 · ${Math.round(f*100)}%`;}}});
    if(controller.signal.aborted)return;
    const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});if(controller.signal.aborted)return;
    videoController=null;openModal('Tu video está listo','15 segundos para compartir la emoción.',`<video class="video-result" src="${url}" controls playsinline preload="metadata" aria-label="Tu invitación en video"></video><a class="btn primary full" href="${url}" download="lumimila-invitacion.mp4">${icon('download')}Guardar archivo MP4</a><p class="local-note">1000 × 1400 píxeles · 15 segundos${design.audio?' · Incluye el audio elegido':' · Sin audio'}</p>`);
  }catch(e){if(controller.signal.aborted)return;videoController=null;openModal('No pudimos crear el video','Tu diseño sigue guardado.',`<p class="notice">${esc(e.message)}</p>`,button('download','Volver a las descargas','back','small'));}
}
$('#audio-upload').addEventListener('change',async event=>{
  const files=[...event.target.files];event.target.value='';if(!files.length||audioBusy)return;
  const design=state.design;audioBusy=true;audioNotice='';renderLeft();const errors=[];let added=0,trimmed=false;
  try{for(const file of files){if((design.audioOptions||[]).length>=3){errors.push('Puedes ofrecer hasta 3 audios por invitación.');break;}try{const result=await uploadAudio(file);if(design.audioOptions?.some(a=>a.id===result.ref.id)){errors.push(`${file.name} ya está en esta invitación.`);continue;}if(state.design!==design)break;remember();(design.audioOptions??=[]).push(result.ref);if(!design.audio)design.audio={...result.ref};added++;trimmed ||= result.trimmed;changed();}catch(e){errors.push(e.message);}}}finally{audioBusy=false;}
  audioNotice=[added?`${added} ${added===1?'audio listo':'audios listos'}.`:'',trimmed?'Se guardaron los primeros 15 segundos.':'',...errors].filter(Boolean).join(' ');renderLeft();toast(errors.length?'Revisa el resultado en Animación.':'Tus audios están listos para elegir.');
});
function fontOptions(selected){
  const custom=listFonts();
  const builtins=`<optgroup label="Incluidas">${FONTS.map(f=>`<option value="${f}" ${selected===f?'selected':''}>${f}</option>`).join('')}</optgroup>`;
  const uploaded=custom.length?`<optgroup label="Mis fuentes">${custom.map(f=>`<option value="${f.id}" ${selected===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</optgroup>`:'';
  const missing=isCustomFont(selected)&&!fontInfo(selected)?`<option value="${selected}" selected>${esc(state.design.fonts?.find(f=>f.id===selected)?.name||'Mi fuente')} · vuelve a subirla</option>`:'';
  return builtins+uploaded+missing;
}
function renderFontsPanel(dest){
  const fonts=listFonts(),selected=getSelected();
  dest.innerHTML=`<div class="eyebrow">Letras con personalidad</div><h2 class="panel-title">Mis fuentes</h2><p class="help">Tus favoritas, para cada ocasión.</p><button class="upload-area font-upload" data-action="upload-font" ${fontBusy?'disabled':''} aria-label="Subir fuentes">${icon('upload')}<strong>${fontBusy?'Guardando tus fuentes…':'Subir fuentes'}</strong><small>.TTF o .OTF · hasta 5 MB por archivo</small></button><p class="font-notice" role="status">${esc(fontNotice)}</p>
  ${fonts.length?`<div class="field"><label for="font-sample">Prueba tus palabras</label><input id="font-sample" value="${esc(fontSample)}" maxlength="80"></div><div class="font-list">${fonts.map(f=>`<article class="font-card ${selected?.font===f.id?'active':''}"><div class="font-card-top"><strong title="${esc(f.name)}">${esc(f.name)}</strong><span>${f.format.toUpperCase()}</span></div><p class="font-card-sample" style="font-family:'${f.id}'">${esc(fontSample||'Un momento especial')}</p><div class="font-card-bottom"><small>${Math.round(f.byteLength/1024)} KB${selected?.font===f.id?' · En este texto':''}</small><button class="btn small" data-action="use-font" data-font="${f.id}" aria-label="Usar ${esc(f.name)}">${selected?.font===f.id?'Aplicada':selected?.type==='text'?'Usar fuente':'Añadir texto'}</button></div></article>`).join('')}</div>`:`<div class="font-empty"><span>Aa</span><strong>Tu colección empieza aquí</strong><p class="help">Sube una fuente para ver una muestra y usarla en tu invitación.</p></div>`}
  <div class="hint-card">${icon('save')}<strong>Siempre con tu diseño</strong><p class="help">Se conservan en este navegador. Al exportar el diseño, se incluyen las fuentes que usaste para llevarlo a otro dispositivo.</p></div>`;
}
function useFont(id){
  if(!fontInfo(id))return;
  remember();let e=getSelected();
  if(!e||e.type!=='text'){e=textLayer(uid(),'Un momento especial',280,38,'#a35147',{font:id,h:70,label:'Mi texto'});state.design.elements.push(e);state.selected=e.id;}
  e.font=id;changed({props:true,left:true});toast(`«${fontInfo(id).name}» aplicada al texto.`);
}
async function exportProject(){
  const fonts=exportFonts(state.design);
  const audioFiles=exportAudio(state.design);
  const json=JSON.stringify({format:'mi-estudio',version:3,design:state.design,fonts,audioFiles},null,2);
  const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(new Blob([json],{type:'application/json'}));});
  openModal('Tu diseño, contigo','Una copia editable para guardar o llevar a otro navegador.',`<p class="notice">Incluye la invitación, sus imágenes, sus opciones de audio y ${fonts.length===1?'la fuente personalizada utilizada':`las ${fonts.length} fuentes personalizadas utilizadas`}. En otro navegador, abre Mis diseños → Importar para recuperarlo.</p><a class="btn primary full" style="margin-top:20px" href="${url}" download="lumimila-diseno.json">${icon('download')}Guardar diseño completo</a>`);
}
$('#font-upload').addEventListener('change',async event=>{
  const files=[...event.target.files];event.target.value='';if(!files.length||fontBusy)return;
  fontBusy=true;fontNotice='';renderLeft();const errors=[];let added=0,duplicates=0;
  try{for(const file of files){try{const result=await uploadFont(file);result.duplicate?duplicates++:added++;}catch(e){errors.push(`${file.name}: ${e.message}`);}}}
  finally{fontBusy=false;}
  fontNotice=[added?`${added===1?'Fuente guardada':`${added} fuentes guardadas`}.`:'',duplicates?`${duplicates===1?'Esa fuente ya está':'Esas fuentes ya están'} en tu colección.`:'',...errors].filter(Boolean).join(' ');
  renderLeft();renderProperties();draw();toast(errors.length?'Revisa el resultado en Mis fuentes.':added?'Tus fuentes están listas para usar.':'La fuente ya estaba guardada.');
});
function renderProperties(){
  const dest=$('#properties');if(!dest)return;const e=getSelected();
  if(!e){dest.innerHTML=`<div class="eyebrow">Tu toque personal</div><div class="empty-properties">${icon('cursor')}<h3>Los detalles<br>hacen la diferencia.</h3><p class="help">Selecciona un texto, una imagen o un elemento para personalizarlo.</p></div>`;return;}
  const prop=(key,label,type='number',attrs='')=>`<div class="field"><label for="prop-${key}">${label}</label><input id="prop-${key}" data-prop="${key}" type="${type}" value="${esc(type==='number'?Math.round(e[key]*10)/10:e[key])}" ${attrs}></div>`;
  dest.innerHTML=`<div class="eyebrow">Hazlo a tu manera</div><div class="selected-heading"><span class="selected-icon">${icon(e.type==='shape'?'shapes':e.type)}</span><div><h3>${e.type==='text'?'Texto seleccionado':e.type==='image'?'Imagen seleccionada':'Elemento seleccionado'}</h3><p>Personaliza cada detalle</p></div></div>
  ${e.type==='text'?`<div class="field"><label for="prop-text">Contenido</label><textarea id="prop-text" data-prop="text" maxlength="500" rows="2">${esc(e.text)}</textarea></div><div class="field-row"><div class="field"><label for="prop-font">Tipografía</label><select id="prop-font" data-prop="font">${fontOptions(e.font)}</select></div>${prop('size','Tamaño','number','min="6" max="120"')}</div>${button('open-fonts','Mis fuentes','text','font-shortcut small')}`:''}
  ${e.type!=='image'?`<div class="field-label" style="margin-bottom:11px">${e.type==='text'?'Color del texto':'Color'}</div><div class="swatches">${COLORS.map(c=>`<button class="swatch ${e.color===c?'active':''}" style="--swatch:${c}" data-color="${c}" aria-label="Color ${c}"></button>`).join('')}<input class="color-custom" type="color" data-prop="color" value="${e.color}" aria-label="Elegir otro color"></div>`:''}
  ${e.type==='text'?`<div class="field-label" style="margin-bottom:8px">Alineación y estilo</div><div class="segmented">${['left','center','right'].map(a=>`<button data-align="${a}" class="${e.align===a?'active':''}" aria-label="Alinear ${a==='left'?'a la izquierda':a==='right'?'a la derecha':'al centro'}">${icon(a)}</button>`).join('')}<button data-action="bold" class="${e.weight>=600?'active':''}" aria-label="Negrita"><b>B</b></button></div>`:''}
  <hr class="section-line">${e.type==='text'?`<label class="toggle-line"><input type="checkbox" data-prop="editable" ${e.editable?'checked':''}><span class="switch"></span><span class="toggle-text">Editable por el cliente</span></label><p class="help indent-help">El cliente podrá cambiar este texto en su propia copia.</p>${e.editable?`<div style="margin-top:16px">${prop('label','Nombre del campo','text','maxlength="80"')}${prop('maxLength','Máximo de caracteres','number','min="1" max="500"')}</div>`:''}`:''}
  <label class="toggle-line"><input type="checkbox" data-prop="locked" ${e.locked?'checked':''}><span class="switch"></span><span class="toggle-text">Fijar posición</span></label><p class="help indent-help">Evita mover este elemento por accidente.</p><hr class="section-line"><div class="field-row equal">${prop('x','Posición X','number',`min="0" max="${W-e.w}" step="1"`)}${prop('y','Posición Y','number',`min="0" max="${H-e.h}" step="1"`)}</div><div class="field-row equal">${prop('w','Ancho','number',`min="10" max="${W-e.x}"`)}${prop('h','Alto','number',`min="1" max="${H-e.y}"`)}</div><div class="right-actions">${button('forward','Al frente','up','small')}${button('backward','Atrás','down','small')}</div><hr class="section-line"><div class="right-actions">${button('duplicate','Duplicar','copy','small')}${button('delete','Eliminar','trash','small')}</div><p class="editor-mode-note">Las descargas conservan el diseño y ajustan el texto para que quepa.</p>`;
}
function fitStage(){const viewport=$('.stage-viewport'),wrap=$('#canvas-wrap');if(!viewport||!wrap||viewport.clientWidth===0)return;const base=Math.min((viewport.clientWidth-54)/W,(viewport.clientHeight-43)/H);const scale=Math.max(.2,base)*state.zoom;wrap.style.width=`${W*scale}px`;wrap.style.height=`${H*scale}px`;$('#zoom-label').textContent=Math.round(scale*100)+'%';showSelection();}
async function draw(){const token=++renderToken,canvas=$('#design-canvas');if(!canvas)return;try{await document.fonts.ready;await Promise.all([document.fonts.load('650 60px Fraunces'),document.fonts.load('400 14px "DM Sans"')]);const temp=document.createElement('canvas');await renderDesign(temp,clone(activeDesign()),2);if(token!==renderToken||!canvas.isConnected)return;canvas.width=temp.width;canvas.height=temp.height;canvas.getContext('2d').drawImage(temp,0,0);showSelection();}catch(error){toast(error.message);}}
function showSelection(){const dest=$('#selection');if(!dest)return;const e=getSelected();if(!e){dest.innerHTML='';return;}dest.innerHTML=`<div class="selection" style="left:${e.x/W*100}%;top:${e.y/H*100}%;width:${e.w/W*100}%;height:${e.h/H*100}%"><span class="selection-caption">${e.locked?'Posición fija':e.type==='text'?'Texto':e.type==='image'?'Imagen':'Elemento'}</span><i class="handle tl"></i>${e.locked?'':'<i class="handle br" data-resize="true"></i>'}</div>`;}
function select(id){state.selected=id;renderProperties();renderLeft();showSelection();}
function addText(kind){remember();const sizes={title:42,subtitle:23,body:13};const labels={title:'Tu título aquí',subtitle:'Un detalle especial',body:'Escribe tu texto aquí'};const e=textLayer(uid(),labels[kind],300,sizes[kind],'#394737',{font:kind==='title'?'Fraunces':'DM Sans',h:sizes[kind]*1.5,label:'Nuevo texto'});state.design.elements.push(e);state.selected=e.id;state.mobile='canvas';render();changed();}
function addShape(shape){remember();const e={id:uid(),type:'shape',shape,x:220,y:300,w:60,h:shape==='line'?3:60,color:'#dba936',label:{star:'Estrella',heart:'Corazón',rect:'Rectángulo',circle:'Círculo',line:'Línea'}[shape],locked:false,editable:false};state.design.elements.push(e);state.selected=e.id;state.mobile='canvas';render();changed();}
function pushLibrary(){const d=clone(state.design),index=state.library.findIndex(x=>x.id===d.id);if(index<0)state.library.push(d);else state.library[index]=d;saveNow();}
function switchDesign(design){pushLibrary();state.design=clone(design);state.selected=state.design.elements.find(e=>e.type==='text')?.id??null;history=[];future=[];group=null;state.mode='editor';state.zoom=1;state.mobile='canvas';saveNow();render();}
function openModal(title,subtitle,content,footer=''){stopPlayback();videoController?.abort();videoController=null;const modal=$('#modal');modal.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${ib('close-modal','Cerrar','close')}</div><div class="modal-body">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function closeModal(){stopPlayback();videoController?.abort();videoController=null;$('#modal').close();}
async function showLibrary(){pushLibrary();openModal('Tus diseños','Un lugar para guardar todas tus ideas.',`<div class="design-list">${state.library.map((d,i)=>`<article class="design-card"><button class="preview" data-open-design="${esc(d.id)}" aria-label="Abrir ${esc(d.name)}"><canvas data-thumbnail="${i}"></canvas></button><div class="design-card-info"><strong>${esc(d.name)}</strong>${ib('library-delete','Eliminar diseño guardado','trash',`data-id="${esc(d.id)}"`)}</div></article>`).join('')}</div><p class="local-note">Guardado en este navegador. Exporta tu diseño para tener una copia de respaldo; puedes importarla en otro dispositivo.</p>`,`${button('import','Importar','upload','small')}${button('export-project','Exportar diseño','download','small')}${button('new-blank','Nuevo diseño','plus','primary small')}`);for(const c of document.querySelectorAll('[data-thumbnail]')){await renderDesign(c,state.library[+c.dataset.thumbnail],.5);}}
function showDownload(){openModal('Listo para compartir','Elige cómo quieres llevarte tu invitación.',`<button class="download-option" data-download="png"><span class="file-icon">${icon('image')}</span><span><strong>Imagen PNG</strong><small>1500 × 2100 px · Para compartir y guardar</small></span>${icon('download')}</button><button class="download-option" data-download="pdf"><span class="file-icon">${icon('file')}</span><span><strong>PDF para imprimir</strong><small>5 × 7 pulgadas · 300 ppp · Sin marcas de corte</small></span>${icon('download')}</button><button class="download-option" data-download="mp4"><span class="file-icon">${icon('spark')}</span><span><strong>Video MP4</strong><small>15 segundos · 1000 × 1400 px · Animación y audio</small></span>${icon('download')}</button><p class="notice">El movimiento y el sonido se incluyen en el MP4. PNG y PDF son imágenes fijas. Solo se descarga tu invitación. Los controles y recuadros de edición no aparecen en el archivo.</p>`);}
function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function download(format){if(format==='mp4')return downloadVideo();const buttons=[...document.querySelectorAll('[data-download]')];buttons.forEach(b=>b.disabled=true);try{await document.fonts.ready;const c=document.createElement('canvas');await renderDesign(c,clone(activeDesign()),3);const name=activeDesign().name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9 -]/g,'').trim().replace(/\s+/g,'-').toLowerCase()||'invitacion';let blob;if(format==='png'){blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw new Error('No se pudo generar la imagen.');}else{const bytes=Uint8Array.from(atob(c.toDataURL('image/jpeg',.98).split(',')[1]),x=>x.charCodeAt(0));blob=jpegToPdf(bytes,1500,2100);}const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});openModal('Tu invitación está lista','Un bonito recuerdo, listo para compartir.',`<div class="download-preview"><img src="${c.toDataURL('image/jpeg',.65)}" alt="Tu invitación lista para descargar"></div><a class="btn primary full" id="ready-download" href="${url}" download="${name}.${format}">${icon('download')}Guardar archivo ${format.toUpperCase()}</a><p class="local-note" style="text-align:center">${format==='pdf'?'5 × 7 pulgadas · PDF de una página para imprimir':'1500 × 2100 píxeles · Imagen de alta resolución'}</p>`,button('download','Elegir otro formato','back','small'));}catch(e){toast(e.message);}finally{buttons.forEach(b=>b.disabled=false);}}

function enterCustomer(){saveNow();state.customer=customerCopy(state.design);try{const saved=JSON.parse(localStorage.getItem('mi-estudio-cliente-'+state.design.id)||'null');if(saved?.sourceUpdatedAt===state.design.updatedAt)state.customer=validateDesign(saved.design);}catch{}state.mode='customer';state.selected=null;render();window.scrollTo(0,0);}
function saveCustomer(){try{localStorage.setItem('mi-estudio-cliente-'+state.design.id,JSON.stringify({sourceUpdatedAt:state.design.updatedAt,design:state.customer}));}catch{toast('No pudimos guardar el avance. Descarga tu invitación antes de cerrar.');}}
function renderCustomer(){const fields=state.customer.elements.filter(e=>e.type==='text'&&e.editable);$('#app').innerHTML=`<div class="customer-shell"><header class="topbar">${brand()}${button('editor','Volver a mi editor','back')}</header><div class="customer-banner">${icon('eye')}Vista de prueba del cliente · Estás editando una copia de tu plantilla</div><main class="customer-main"><section class="customer-art" aria-label="Vista previa de tu invitación"><span class="preview-label"><i></i>Tu invitación en tiempo real</span><div class="canvas-wrap"><canvas id="design-canvas" aria-label="Vista previa de la invitación personalizada"></canvas></div><p class="help">Cada pequeño detalle, a tu manera.</p></section><div class="customer-edit"><div class="customer-title"><div class="eyebrow">Un día para recordar</div><h1>La celebración<br>empieza contigo.</h1><p>Cambia los datos, mira cómo queda y descarga<br class="desktop-br"> una invitación tan especial como tu festejo.</p></div><form class="customer-form" onsubmit="return false">${fields.map(e=>`<div class="field"><label for="customer-${esc(e.id)}">${esc(e.label)}</label><input id="customer-${esc(e.id)}" data-customer="${esc(e.id)}" value="${esc(e.text)}" maxlength="${e.maxLength}" autocomplete="off"><div class="char-count" data-count="${esc(e.id)}">${e.text.length} / ${e.maxLength}</div></div>`).join('')}${!fields.length?'<p class="notice">Esta plantilla no tiene campos editables. Actívalos desde tu editor.</p>':''}${renderAudioChoices(state.customer,true)}${button('preview-motion','Ver animación y escuchar','eye','full motion-preview','type="button"')}${button('download','Descargar mi invitación','download','primary full','type="button"')}${button('reset-customer','Restaurar los datos de ejemplo',null,'ghost full small','type="button"')}<p class="local-note">Tu avance se guarda en este navegador.<br>Tu plantilla original permanece intacta.</p></form></div></main></div>`;draw();}
const actions={
  'preview-motion':previewAnimation,'replay-motion':previewAnimation,
  'set-effect':b=>{remember();state.design.animation=b.dataset.effect;changed({left:true});},
  'upload-audio':()=>{if(!audioBusy)$('#audio-upload').click();},
  'choose-audio':b=>chooseAudio(b.dataset.id),
  'listen-audio':b=>listenAudio(b.dataset.id),
  'remove-audio':b=>{stopPlayback();remember();state.design.audioOptions=(state.design.audioOptions||[]).filter(a=>a.id!==b.dataset.id);if(state.design.audio?.id===b.dataset.id)state.design.audio=null;changed({left:true});},
  'open-fonts':()=>{state.tab='fonts';state.mobile='tools';render();},
  'upload-font':()=>{if(!fontBusy)$('#font-upload').click();},
  'use-font':b=>useFont(b.dataset.font),
  'download':showDownload,'library':showLibrary,'customer':enterCustomer,'editor':()=>{state.mode='editor';state.selected=state.design.elements.find(e=>e.type==='text')?.id;render();},
  'close-modal':closeModal,'save-template':()=>{pushLibrary();toast(storageProblem?'Descarga una copia para conservar tu plantilla.':'Plantilla guardada en Mis diseños.');},
  'rename':()=>{openModal('Un nombre para tu diseño','Así lo encontrarás en tu colección.',`<div class="field"><label for="design-title-input">Nombre del diseño</label><input id="design-title-input" value="${esc(state.design.name)}" maxlength="80"></div>`,button('confirm-rename','Guardar nombre','check','primary'));$('#design-title-input').select();},
  'confirm-rename':()=>{const value=$('#design-title-input').value.trim();if(!value)return;remember();state.design.name=value;closeModal();render();changed();},
  'undo':()=>{if(!history.length)return;future.push(clone(state.design));state.design=history.pop();group=null;render();queueSave();},
  'redo':()=>{if(!future.length)return;history.push(clone(state.design));state.design=future.pop();group=null;render();queueSave();},
  'zoom-in':()=>{state.zoom=clamp(state.zoom+.15,.5,2);fitStage();},'zoom-out':()=>{state.zoom=clamp(state.zoom-.15,.5,2);fitStage();},'zoom-fit':()=>{state.zoom=1;fitStage();},
  'bold':()=>{const e=getSelected();if(!e)return;remember();e.weight=e.weight>=600?400:700;changed({props:true});},
  'duplicate':()=>{const e=getSelected();if(!e)return;remember();const copy=clone(e);copy.id=uid();copy.x=clamp(e.x+12,0,W-e.w);copy.y=clamp(e.y+12,0,H-e.h);copy.label=e.label+' (copia)';state.design.elements.push(copy);state.selected=copy.id;changed({props:true,left:true});},
  'delete':()=>{if(!getSelected())return;remember();state.design.elements=state.design.elements.filter(e=>e.id!==state.selected);state.selected=null;changed({props:true,left:true});},
  'forward':()=>reorder(1),'backward':()=>reorder(-1),
  'upload-image':()=>{uploadMode='image';$('#image-upload').click();},'upload-background':()=>{uploadMode='background';$('#image-upload').click();},
  'remove-background':()=>{remember();state.design.backgroundImage=null;changed({left:true});},'birthday-background':()=>{remember();state.design.backgroundImage='./assets/fiesta-bg.png';changed({left:true});},
  'new-birthday':()=>{closeModal();switchDesign(birthday());toast('Una nueva invitación para celebrar.');},'new-blank':()=>{closeModal();switchDesign(blank());},
  'export-project':exportProject,
  'import':()=>$('#design-import').click(),
  'library-delete':b=>{const id=b.dataset.id;state.library=state.library.filter(d=>d.id!==id);saveNow();closeModal();toast('Copia guardada eliminada. El diseño abierto sigue disponible.');},
  'reset-customer':()=>{state.customer=customerCopy(state.design);saveCustomer();renderCustomer();toast('Datos de ejemplo restaurados.');}
};
function reorder(delta){const idx=state.design.elements.findIndex(e=>e.id===state.selected),next=idx+delta;if(idx<0||next<0||next>=state.design.elements.length)return;remember();[state.design.elements[idx],state.design.elements[next]]=[state.design.elements[next],state.design.elements[idx]];changed({left:true});}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action){const fn=actions[b.dataset.action];if(fn)Promise.resolve(fn(b)).catch(e=>toast(e.message));}else if(b.dataset.tab){state.tab=b.dataset.tab;renderLeft();}else if(b.dataset.select){select(b.dataset.select);}else if(b.dataset.addText){addText(b.dataset.addText);}else if(b.dataset.shape){addShape(b.dataset.shape);}else if(b.dataset.color){const e=getSelected();if(e){remember();e.color=b.dataset.color;changed({props:true});}}else if(b.dataset.align){const e=getSelected();if(e){remember();e.align=b.dataset.align;changed({props:true});}}else if(b.dataset.mobile){state.mobile=b.dataset.mobile;$('.workspace').dataset.mobile=state.mobile;document.querySelectorAll('[data-mobile]').forEach(t=>{if(t.tagName==='BUTTON')t.classList.toggle('active',t.dataset.mobile===state.mobile);});fitStage();}else if(b.dataset.openDesign){const d=state.library.find(d=>d.id===b.dataset.openDesign);if(d){closeModal();switchDesign(d);}}else if(b.dataset.download)download(b.dataset.download);});
function updateProperty(input){const e=getSelected(),key=input.dataset.prop;if(!e||!key)return;let value=input.type==='checkbox'?input.checked:input.value;if(input.type==='number'){if(value==='')return;value=Number(value);if(!Number.isFinite(value))return;const bounds={size:[6,120],maxLength:[1,500],x:[0,W-e.w],y:[0,H-e.h],w:[10,W-e.x],h:[1,H-e.y]};if(bounds[key])value=clamp(value,...bounds[key]);if(key==='maxLength')value=Math.round(value);if((key==='x'||key==='y'||key==='w'||key==='h')&&e.locked){toast('Desactiva «Fijar posición» para cambiar el tamaño o moverlo.');renderProperties();return;}}
  if(key==='font'&&(!FONTS.includes(value)&&!fontInfo(value)))return;
  if(e[key]===value)return;
  remember('prop-'+key);e[key]=value;changed({props:input.type==='checkbox',left:['text','label','editable','locked'].includes(key)});
}
document.addEventListener('input',event=>{const t=event.target;if(t.id==='audio-volume'){const selected=state.design.audio;if(!selected)return;remember('audio-volume');selected.volume=Number(t.value)/100;const option=state.design.audioOptions.find(a=>a.id===selected.id);option.volume=selected.volume;$('#audio-volume-value').textContent=t.value+'%';changed();}else if(t.id==='font-sample'){fontSample=t.value;document.querySelectorAll('.font-card-sample').forEach(p=>p.textContent=fontSample||'Un momento especial');}else if(t.dataset.prop)updateProperty(t);else if(t.dataset.background){remember('background');state.design.background=t.value;changed();}else if(t.dataset.customer){setCustomerText(state.customer,t.dataset.customer,t.value);const count=document.querySelector(`[data-count="${CSS.escape(t.dataset.customer)}"]`);if(count)count.textContent=`${t.value.length} / ${t.maxLength}`;draw();saveCustomer();}});
document.addEventListener('focusout',()=>{group=null;});
document.addEventListener('change',event=>{if(event.target.dataset.prop&&event.target.tagName==='SELECT')updateProperty(event.target);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',e=>{if($('#modal').open){if(e.key==='Enter'&&$('#design-title-input')){e.preventDefault();actions['confirm-rename']();}return;}if(e.target.matches('input,textarea,select,[contenteditable]'))return;if(state.mode!=='editor')return;const cmd=e.ctrlKey||e.metaKey;if(cmd&&e.key.toLowerCase()==='z'){e.preventDefault();actions[e.shiftKey?'redo':'undo']();return;}if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();actions['save-template']();return;}if(cmd&&e.key.toLowerCase()==='d'){e.preventDefault();actions.duplicate();return;}if(e.key==='Escape'){select(null);return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();actions.delete();return;}const selected=getSelected();if(selected&&!selected.locked&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();remember('keyboard');const step=e.shiftKey?10:1;moveElement(selected,e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0);changed({props:true});}});
document.addEventListener('keyup',()=>{group=null;});
let drag=null;
document.addEventListener('pointerdown',event=>{if(state.mode!=='editor'||event.button!==0)return;const resize=event.target.closest('[data-resize]'),canvas=event.target.closest('#design-canvas');if(!resize&&!canvas)return;const rect=$('#design-canvas').getBoundingClientRect(),x=(event.clientX-rect.left)*W/rect.width,y=(event.clientY-rect.top)*H/rect.height;const el=resize?getSelected():hitTest(state.design.elements,x,y);if(!el){select(null);return;}select(el.id);if(el.locked)return;drag={id:el.id,x:event.clientX,y:event.clientY,s:rect.width/W,origin:clone(el),resize:!!resize,changed:false};event.preventDefault();$('#design-canvas').focus({preventScroll:true});});
document.addEventListener('pointermove',event=>{if(!drag)return;const dx=(event.clientX-drag.x)/drag.s,dy=(event.clientY-drag.y)/drag.s;if(!drag.changed&&Math.abs(dx)+Math.abs(dy)<2)return;if(!drag.changed){remember();drag.changed=true;}const el=state.design.elements.find(e=>e.id===drag.id);if(!el)return;const o=drag.origin;if(drag.resize){el.w=clamp(o.w+dx,20,W-o.x);el.h=clamp(o.h+dy,el.type==='text'?10:1,H-o.y);if(el.type==='image'){const ratio=o.w/o.h;el.h=Math.min(el.w/ratio,H-o.y);el.w=el.h*ratio;}}else{el.x=clamp(o.x+dx,0,W-o.w);el.y=clamp(o.y+dy,0,H-o.h);}draw();event.preventDefault();},{passive:false});
function stopDrag(){if(drag?.changed){changed({props:true});}drag=null;}
document.addEventListener('pointerup',stopDrag);document.addEventListener('pointercancel',stopDrag);
$('#image-upload').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Usa una imagen PNG, JPG o WebP.');return;}if(file.size>12*1024*1024){toast('La imagen debe pesar menos de 12 MB.');return;}try{const src=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.onerror=j;reader.readAsDataURL(file);});const img=await loadImage(src),c=document.createElement('canvas'),max=uploadMode==='background'?2100:1500,scale=Math.min(1,max/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const normalized=c.toDataURL(file.type==='image/png'?'image/png':'image/jpeg',.9);remember();if(uploadMode==='background')state.design.backgroundImage=normalized;else{const w=Math.min(230,img.width),h=Math.min(300,w*img.height/img.width),actualW=h*img.width/img.height;const el={id:uid(),type:'image',src:normalized,x:(W-actualW)/2,y:(H-h)/2,w:actualW,h,label:file.name.slice(0,80),locked:false,editable:false};state.design.elements.push(el);state.selected=el.id;}state.mobile='canvas';render();changed();toast('Imagen añadida a tu invitación.');}catch{toast('No se pudo leer la imagen. Prueba con otro archivo.');}});
$('#design-import').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>90*1024*1024){toast('El archivo es demasiado grande.');return;}try{const raw=JSON.parse(await file.text());if(raw.format!=='mi-estudio'||![1,2,3].includes(raw.version))throw new Error('Selecciona un archivo exportado desde Lumimila.');const design=validateDesign(raw.design);await importFonts(raw.fonts||[],design);await importAudio(raw.audioFiles||[],design);design.id=uid();closeModal();switchDesign(design);toast('Diseño importado.');}catch(e){toast(e.message||'No pudimos importar el diseño.');}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
window.addEventListener('resize',fitStage);
window.addEventListener('beforeunload',()=>{if(saveTimer)saveNow();});
try{const errors=await initializeFonts();if(errors.length)fontNotice=errors.join(' ');}catch(e){fontNotice=e.message;}
try{await initializeAudio();}catch(e){audioNotice=e.message;}
render();if(fontNotice)toast(fontNotice);if(audioNotice)toast(audioNotice);if(storageProblem)toast('No pudimos recuperar el último diseño. Puedes importar tu respaldo.');
